function listTools() {
  return [...tools];
}
function getTool(name) {
  return tools.find((entry) => entry.name === name);
}
async function invokeTool(service, name, args) {
  const descriptor = getTool(name);
  if (!descriptor) {
    return {
      ok: false,
      error: { code: "TOOL_NOT_FOUND", message: `Unknown tool: ${name}` }
    };
  }
  try {
    const data = await descriptor.handler({ service }, args);
    if (data && typeof data === "object" && "ok" in data && data.ok === false) {
      return data;
    }
    return { ok: true, data };
  } catch (error) {
    if (error instanceof ServiceError) {
      return {
        ok: false,
        error: {
          code: error.code,
          message: error.message,
          details: error.details
        }
      };
    }
    const message = error instanceof Error ? error.message : String(error);
    return { ok: false, error: { code: "TOOL_EXECUTION_FAILED", message } };
  }
}
function buildToolManifest() {
  return {
    generatedAt: "static",
    count: tools.length,
    tools: tools.map((entry) => ({
      name: entry.name,
      title: entry.title,
      description: entry.description,
      category: entry.category,
      mutating: entry.mutating === true,
      requiresAi: entry.requiresAi === true,
      inputSchema: zodToJsonSchema(external_exports.object(entry.inputSchema), {
        target: "jsonSchema7",
        $refStrategy: "none"
      })
    }))
  };
}

